// Generated by Static Site Exporter. Declares a collection for each folder
// under src/content/, with a schema that accepts any front matter.
import { defineCollection } from 'astro:content';
import { file, glob } from 'astro/loaders';
import { z } from 'astro/zod';

interface CategoryNode {
	name: string;
	slug: string;
	children?: CategoryNode[];
}

const flattenCategories = (text: string) => {
	const roots = JSON.parse(text) as CategoryNode[];
	const entries: Array<{ id: string; name: string; slug: string; path: string; parent?: string }> = [];

	const visit = (node: CategoryNode, parent?: string) => {
		const path = parent ? `${parent}/${node.slug}` : node.slug;
		entries.push({
			id: path.replaceAll('/', '-'),
			name: node.name,
			slug: node.slug,
			path,
			...(parent ? { parent } : {}),
		});
		node.children?.forEach((child) => visit(child, path));
	};

	roots.forEach((root) => visit(root));
	return entries;
};

const blog = defineCollection({
	// Each post lives in src/content/blog/YYYY/MM/<slug>/index.md beside its images.
	loader: glob({ base: './src/content/blog', pattern: '**/*.{md,mdx}' }),
	// Type-check frontmatter using a schema
    schema: ({ image }) => 
		z.object({
			id: z.int(),
			title: z.string(),
			excerpt: z.string(),
			date: z.coerce.date(),
			author: z.string().optional(),
			categories: z.array(z.string()).default([]),
			tags: z.array(z.string()).default([]),
			permalink: z.string().optional(),
			heroImage: image().optional(),
		}).transform(({ date, ...frontmatter }) => ({
			...frontmatter,
			pubDate: date,
			description: frontmatter.excerpt,
		})),
});

const categories = defineCollection({
	loader: file('./src/content/categories.json', { parser: flattenCategories }),
	schema: z.object({
		name: z.string(),
		slug: z.string(),
		path: z.string(),
		parent: z.string().optional(),
		description: z.string().optional(),
	}),
});

const tags = defineCollection({
	loader: file('./src/content/tags.json'),
	schema: z.object({
		name: z.string(),
		description: z.string().optional(),
	}),
});

const pages = defineCollection({
	// Each page lives in src/content/pages/<slug>/index.md beside its images.
	loader: glob({ base: './src/content/pages', pattern: '**/*.{md,mdx}' }),
	// Type-check frontmatter using a schema
	schema: ({ image }) =>
		z.object({
			title: z.string(),
			description: z.string().optional(),
			excerpt: z.string().optional(),
			// Transform string to Date object
			date: z.coerce.date().optional(),
			pubDate: z.coerce.date().optional(),
			updatedDate: z.coerce.date().optional(),
			draft: z.boolean().optional(),
			permalink: z.string().optional(),
			image: image().optional(),
		}),
});

export const collections = { blog, pages, categories, tags };
